from pathlib import Path
from typing import Any, Dict, List, Optional
from detranspiler.java.gen.pe_context import build_pe_context
from detranspiler.java.gen.prepare import prepare_core
from detranspiler.java.gen.state import GenerationState

def build_generation_state(*, exports: List[str], pseudo_c_path: Optional[Path], functions_json_path: Optional[Path]=None, class_name: str='NativeDecompiled', max_functions: int=2000, max_pseudo_c_chars: int=2000000, jni_register: Optional[Dict[str, Any]]=None, jni_calls: Optional[Dict[str, Any]]=None, jar_path: Optional[Path]=None, binary_path: Optional[Path]=None, callgraph: Optional[Dict[str, Any]]=None, extra_seed_strings: Optional[List[str]]=None, flattening: Optional[Dict[str, Any]]=None, anti_analysis: Optional[Dict[str, Any]]=None, jar_sources_dir: Optional[Path]=None, deobfuscation: Optional[Dict[str, Any]]=None, string_decrypt: Optional[Dict[str, Any]]=None, string_symbol_map: Optional[Dict[str, str]]=None) -> GenerationState:
    core = prepare_core(exports=exports, pseudo_c_path=pseudo_c_path, functions_json_path=functions_json_path, class_name=class_name, max_functions=max_functions, max_pseudo_c_chars=max_pseudo_c_chars, jni_calls=jni_calls, jar_path=jar_path, callgraph=callgraph, extra_seed_strings=extra_seed_strings, flattening=flattening, jar_sources_dir=jar_sources_dir, deobfuscation=deobfuscation, string_decrypt=string_decrypt, string_symbol_map=string_symbol_map)
    pe = build_pe_context(pseudo_c_text=core['pseudo_c_text'], pseudo_c_path=pseudo_c_path, jni_register=jni_register, binary_path=binary_path, extra_seed_strings=core['extra_seed_strings'], jar_meta=core['jar_meta'])
    return GenerationState(pseudo_c_text=core['pseudo_c_text'], by_name=core['by_name'], ghidra_funcs=core['ghidra_funcs'], jar_meta=core['jar_meta'], jni_hints=core['jni_hints'], flat_hints=core['flat_hints'], recovery_strategy=core['recovery_strategy'], jar_index=core['jar_index'], helper_blocks=core['helper_blocks'], sig_by_raw=core['sig_by_raw'], sig_by_sanitized=core['sig_by_sanitized'], method_items=core['method_items'], class_ident=core['class_ident'], strings_by_addr=pe['strings_by_addr'], dat_ptr_values=pe['dat_ptr_values'], jar_seed_strings=pe['jar_seed_strings'], bin_seed_strings=pe['bin_seed_strings'], read_string_at_va=pe['read_string_at_va'], read_u64_at_va=pe['read_u64_at_va'], jni_calls=jni_calls, jni_register=jni_register, flattening=flattening, anti_analysis=anti_analysis, callgraph=callgraph)
